sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;

    c.clearSearch = function() {
        c.search = '';

        $timeout(function() {
            var searchInput = document.getElementById('aes-announcement-search');

            if (searchInput) {
                searchInput.focus();
            }
        });
    };
};

sp_widget.css:
/* ============================================================
   AES - ANNOUNCEMENT HEADER
   ============================================================ */

.aes-page-header {
  width: 100%;
  margin: 0;
  padding: $aes-header-padding-y 0;

  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;

  border-radius: 0;
}


/* ============================================================
   CONTENT
   ============================================================ */

.aes-page-header__content {
  display: grid;
  grid-template-columns: $aes-header-logo-size 1fr;
  column-gap: $aes-header-logo-gap;
  align-items: start;

  width: 100%;
  max-width: $aes-header-content-width;
  margin: 0;
  padding: 0 $aes-header-padding-x;
}


/* ============================================================
   LOGO
   ============================================================ */

.aes-page-header__logo {
  display: block;

  width: auto;
  height: $aes-header-logo-size;

  align-self: start;
}


/* ============================================================
   MAIN CONTENT
   ============================================================ */

.aes-page-header__main {
  min-width: 0;
}


/* ============================================================
   HEADING
   ============================================================ */

.aes-page-header__heading {
  margin: 0 0 $aes-header-search-gap;
}


/* Title */

.aes-page-header__title {
  display: flex;
  align-items: center;

  min-height: $aes-header-logo-size;
  margin: 0;

  color: $aes-header-text-color;
  font-size: $aes-header-title-size;
  font-weight: $aes-header-title-weight;
  line-height: 1;
}


/* Subtitle */

.aes-page-header__subtitle {
  margin: $aes-header-heading-gap 0 0;

  color: $aes-header-secondary-text-color;
  font-size: $aes-header-subtitle-size;
  font-style: $aes-header-subtitle-style;
  line-height: 1.4;
}


/* ============================================================
   SEARCH
   ============================================================ */

.aes-page-header__search {
  position: relative;
  width: 100%;
  max-width: $aes-header-search-width;
}


/* Search icon */
.aes-page-header__search-icon {
  position: absolute;
  top: 50%;
  left: 16px;
  z-index: 2;
  color: $aes-header-secondary-text-color;
  font-size: 16px;
  transform: translateY(-50%);
  pointer-events: none;
}


/* Search input */

.aes-page-header__search-input {
  width: 100%;
  height: 44px;
  padding: 10px 44px;
  color: $aes-header-text-color;
  background-color: transparent;
  border: 1px solid $border-secondary;
  border-radius: $aes-radius-lg;
  box-shadow: none;
  outline: 0;
  transition:
    background-color $aes-transition-fast,
    border-color $aes-transition-fast,
    box-shadow $aes-transition-fast,
    color $aes-transition-fast;
}


/* Placeholder */

.aes-page-header__search-input::placeholder {
  color: $aes-header-secondary-text-color;
  opacity: 1;
}


/* Empty + focus */

.aes-page-header__search-input:focus {
  color: $aes-header-text-color;
  background-color: transparent;

  border-color: $aes-accent;
  box-shadow: 0 0 0 1px $aes-accent;

  outline: 0;
}


/* ============================================================
   SEARCH - HAS VALUE
   ============================================================ */

.aes-page-header__search-input--has-value {
  color: $input-color;
  background-color: $input-bg;
  border-color: $input-border;
}


/* Has value + focus */

.aes-page-header__search-input--has-value:focus {
  color: $input-color;
  background-color: $input-bg;

  border-color: $aes-accent;
  box-shadow: 0 0 0 1px $aes-accent;
}


/* Search icon when input contains text */

.aes-page-header__search-icon--has-value {
  color: $text-tertiary;
}


/* ============================================================
   CLEAR SEARCH
   ============================================================ */

.aes-page-header__search-clear {
  position: absolute;
  top: 50%;
  right: 12px;
  z-index: 2;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;
  padding: 0;

  color: $text-tertiary;
  background: transparent;

  border: 0;
  border-radius: 50%;

  transform: translateY(-50%);
  cursor: pointer;

  transition:
    color $aes-transition-fast,
    background-color $aes-transition-fast;
}

.aes-page-header__search-clear:hover {
  color: $text-primary;
  background-color: $background-secondary;
}

.aes-page-header__search-clear:focus {
  color: $text-primary;

  outline: 1px solid $aes-accent;
  outline-offset: 1px;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 767px) {

  .aes-page-header {
    padding: $aes-space-2xl 0;
  }

  .aes-page-header__content {
    grid-template-columns: 42px 1fr;
    column-gap: $aes-space-md;

    padding: 0 $aes-space-xl;
  }

  .aes-page-header__logo {
    height: 42px;
  }

  .aes-page-header__title {
    min-height: 42px;
    font-size: $font-size-h2;
  }

  .aes-page-header__heading {
    margin-bottom: $aes-space-2xl;
  }

  .aes-page-header__search {
    max-width: 100%;
  }
}
